**What was changed (UNROLL only):**

1. **`MEAN_J`** loop: added `#pragma HLS UNROLL factor=8`. The column dimension `j` is independent across iterations, and both `data_tile` (dim 2) and `mean_acc` (dim 1) already have `cyclic factor=8` partitioning, so 8 columns can be processed in parallel. (Restructured to pipeline the `ii` loop with unrolled `j` so the 8-way parallel column accesses align with partitioning.)

2. **`MEAN_FIN`** loop: added `#pragma HLS UNROLL factor=8` — independent per-column finalization, matched to `mean_acc`/`mean_l` partitioning.

3. **`COV_INIT_J`** loop: added `#pragma HLS UNROLL factor=8` — independent initialization, matched to `cov_acc` dim 2 partitioning.

4. **`CENTER_J`** loop: added `#pragma HLS UNROLL factor=8` — independent per-column subtraction, matched to `data_tile` dim 2 and `mean_l` partitioning.

All unroll factors are 8 (power of 2) and match existing array partitioning factors, so no partitioning changes were needed. The `COV_K` reduction loop was left unrolled-free since its parallel access pattern is over rows (dim 1 of `data_tile`, which is not partitioned) — unrolling it would require partitioning the large `TILE_N` dimension, which the guards advise against ("do not complete-partition large arrays blindly").

Looking at this code, I'll apply double buffering to the tile loops. I'll create two copies of `data_tile` and add load/compute helper functions that accept a buffer-select flag, allowing load of the next tile to overlap with compute of the current tile.

```cpp
#include "covariance.h"
#include <string.h>

#define TILE_N 256

// ---- Load helper: brings a tile of rows into the selected local buffer ----
static void load_tile(double data[N + 0][M + 0],
                      double tile0[TILE_N][M],
                      double tile1[TILE_N][M],
                      int t, int tn, int m, bool flag)
{
  if (!flag)
    {
    LOAD_T0:
      for (int ii = 0; ii < tn; ii++)
        {
#pragma HLS LOOP_TRIPCOUNT min=1 max=TILE_N
          memcpy(tile0[ii], &data[t + ii][0], m * sizeof(double));
        }
    }
  else
    {
    LOAD_T1:
      for (int ii = 0; ii < tn; ii++)
        {
#pragma HLS LOOP_TRIPCOUNT min=1 max=TILE_N
          memcpy(tile1[ii], &data[t + ii][0], m * sizeof(double));
        }
    }
}

// ---- Mean compute helper: accumulate column sums from selected buffer ----
static void compute_mean(double tile0[TILE_N][M],
                         double tile1[TILE_N][M],
                         double mean_acc[M],
                         int tn, int m, bool flag)
{
  if (!flag)
    {
    MEAN_I0:
      for (int ii = 0; ii < tn; ii++)
        {
#pragma HLS LOOP_TRIPCOUNT min=1 max=TILE_N
        MEAN_J0:
          for (int j = 0; j < m; j++)
            {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
              mean_acc[j] += tile0[ii][j];
            }
        }
    }
  else
    {
    MEAN_I1:
      for (int ii = 0; ii < tn; ii++)
        {
#pragma HLS LOOP_TRIPCOUNT min=1 max=TILE_N
        MEAN_J1:
          for (int j = 0; j < m; j++)
            {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
              mean_acc[j] += tile1[ii][j];
            }
        }
    }
}

// ---- Covariance compute helper: center + accumulate products ----
static void compute_cov(double tile0[TILE_N][M],
                        double tile1[TILE_N][M],
                        double cov_acc[M][M],
                        double mean_l[M],
                        int tn, int m, bool flag)
{
  if (!flag)
    {
      // center
    CENTER_I0:
      for (int ii = 0; ii < tn; ii++)
        {
#pragma HLS LOOP_TRIPCOUNT min=1 max=TILE_N
        CENTER_J0:
          for (int j = 0; j < m; j++)
            {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
              tile0[ii][j] -= mean_l[j];
            }
        }
      // covariance products
    COV_I0:
      for (int i = 0; i < m; i++)
        {
        COV_J0:
          for (int j = i; j < m; j++)
            {
              double acc = cov_acc[i][j];
            COV_K0:
              for (int k = 0; k < tn; k++)
                {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=1 max=TILE_N
#pragma HLS DEPENDENCE variable=tile0 inter false
                  acc += tile0[k][i] * tile0[k][j];
                }
              cov_acc[i][j] = acc;
            }
        }
    }
  else
    {
      // center
    CENTER_I1:
      for (int ii = 0; ii < tn; ii++)
        {
#pragma HLS LOOP_TRIPCOUNT min=1 max=TILE_N
        CENTER_J1:
          for (int j = 0; j < m; j++)
            {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
              tile1[ii][j] -= mean_l[j];
            }
        }
      // covariance products
    COV_I1:
      for (int i = 0; i < m; i++)
        {
        COV_J1:
