#include "covariance.h"
#include <string.h>
#include <ap_int.h>

#define TILE_N 256
#define LARGE_BUS 512
typedef ap_uint<LARGE_BUS> MARS_WIDE_BUS_TYPE;

// ---- Wide-bus helper functions ----
// Read `size_bytes` bytes from wide-bus memory `bus` (byte offset) into double buffer.
static void memcpy_wide_bus_read_double(double *buffer,
                                        MARS_WIDE_BUS_TYPE *bus,
                                        long byte_offset,
                                        int size_bytes)
{
  const int DOUBLES_PER_BUS = LARGE_BUS / 64; // 8 doubles per 512-bit word
  int num_doubles = size_bytes / (int)sizeof(double);
  long word_base = byte_offset / (LARGE_BUS / 8); // starting 512-bit word index
  int elem_in_word = (int)((byte_offset % (LARGE_BUS / 8)) / sizeof(double));

  int produced = 0;
  long w = word_base;
  int e = elem_in_word;
READ_LOOP:
  while (produced < num_doubles)
    {
#pragma HLS LOOP_TRIPCOUNT min=1 max=256
      MARS_WIDE_BUS_TYPE word = bus[w];
    READ_INNER:
      for (; e < DOUBLES_PER_BUS && produced < num_doubles; e++)
        {
#pragma HLS PIPELINE II=1
          ap_uint<64> bits = word.range(64 * e + 63, 64 * e);
          unsigned long long ull = (unsigned long long)bits;
          double d;
          memcpy(&d, &ull, sizeof(double));
          buffer[produced] = d;
          produced++;
        }
      e = 0;
      w++;
    }
}

// Write `size_bytes` bytes from double buffer into wide-bus memory `bus` (byte offset).
static void memcpy_wide_bus_write_double(MARS_WIDE_BUS_TYPE *bus,
                                         double *buffer,
                                         long byte_offset,
                                         int size_bytes)
{
  const int DOUBLES_PER_BUS = LARGE_BUS / 64;
  int num_doubles = size_bytes / (int)sizeof(double);
  long word_base = byte_offset / (LARGE_BUS / 8);
  int elem_in_word = (int)((byte_offset % (LARGE_BUS / 8)) / sizeof(double));

  int consumed = 0;
  long w = word_base;
  int e = elem_in_word;
WRITE_LOOP:
  while (consumed < num_doubles)
    {
#pragma HLS LOOP_TRIPCOUNT min=1 max=256
      MARS_WIDE_BUS_TYPE word = bus[w]; // read-modify-write to preserve partial words
    WRITE_INNER:
      for (; e < DOUBLES_PER_BUS && consumed < num_doubles; e++)
        {
#pragma HLS PIPELINE II=1
          double d = buffer[consumed];
          unsigned long long ull;
          memcpy(&ull, &d, sizeof(double));
          ap_uint<64> bits = (ap_uint<64>)ull;
          word.range(64 * e + 63, 64 * e) = bits;
          consumed++;
        }
      bus[w] = word;
      e = 0;
      w++;
    }
}

